msgs = [user_msg]
while True:
    r = client.converse(modelId=M, messages=msgs, toolConfig=TOOLS)
    msg, why = r["output"]["message"], r["stopReason"]
    if why == "tool_use":
        msgs.append(msg)
        call = next(b["toolUse"] for b in msg["content"] if "toolUse" in b)
        result = run_tool(call["name"], call["input"])
        msgs.append(tool_result_message(call["toolUseId"], result))
    elif why == "end_turn":
        return msg
    elif why == "max_tokens":
        return mark_truncated(msg)
    elif why == "guardrail_intervened":
        return blocked_reply()
    else:
        return fallback(why)
